// ---------------------------------------------------------------------------
// Capability-surface helpers
// ---------------------------------------------------------------------------

fn read_method(
    name: &str,
    subid: &str,
    args: serde_json::Value,
    required_capability: Option<&str>,
) -> MethodDecl {
    MethodDecl {
        name: name.to_string(),
        args,
        returns: None,
        side_effect: SideEffect::Read,
        idempotent: true,
        required_capability: required_capability.map(|s| s.to_string()),
        subid: subid.to_string(),
    }
}

fn mutation_method(
    name: &str,
    subid: &str,
    args: serde_json::Value,
    required_capability: Option<&str>,
    idempotent: bool,
) -> MethodDecl {
    MethodDecl {
        name: name.to_string(),
        args,
        returns: None,
        side_effect: SideEffect::Mutation,
        idempotent,
        required_capability: required_capability.map(|s| s.to_string()),
        subid: subid.to_string(),
    }
}

fn signal_decl(name: &str, subid: &str, payload: Option<serde_json::Value>) -> SignalDecl {
    SignalDecl {
        name: name.to_string(),
        payload,
        subid: subid.to_string(),
    }
}

fn subids_from(
    methods: &HashMap<String, MethodDecl>,
    signals: &[SignalDecl],
) -> HashMap<String, String> {
    let mut map = HashMap::new();
    for (name, decl) in methods {
        map.insert(name.clone(), decl.subid.clone());
    }
    for sig in signals {
        map.insert(sig.name.clone(), sig.subid.clone());
    }
    map
}

fn empty_args() -> serde_json::Value {
    serde_json::json!({"type": "object", "properties": {}, "additionalProperties": false})
}

fn state_changed_payload() -> Option<serde_json::Value> {
    Some(
        serde_json::json!({"type": "object", "properties": {"plugin": {"type": "string"}, "timestamp": {"type": "integer"}}}),
    )
}

fn readonly_any(description: &str) -> FieldSchema {
    FieldSchema {
        field_type: FieldType::Any,
        required: false,
        description: description.to_string(),
        default: None,
        example: None,
        constraints: Vec::new(),
        read_only: true,
        read_only_when: None,
    }
}

fn with_caps(
    mut schema: PluginSchema,
    methods: HashMap<String, MethodDecl>,
    signals: Vec<SignalDecl>,
    guarantees: PluginCapabilities,
) -> PluginSchema {
    schema.subids = subids_from(&methods, &signals);
    schema.methods = methods;
    schema.signals = signals;
    schema.guarantees = guarantees;
    schema
}

/// Format a plugin's live state into a `PluginSchema`.
///
/// This is a *formatter*, not a schema authority — nothing here is indexed. The
/// plugin's `query_current_state()` (its `*State` struct) is the single source
/// of truth; field types are inferred from that state, so the schema can never
/// drift from what the plugin actually reports. To add a field, add it to the
/// plugin state — never hand-write a field definition.
pub(crate) fn schema_from_state(
    name: &str,
    category: &str,
    version: &str,
    description: &str,
    state: &Value,
) -> PluginSchema {
    use simd_json::prelude::*;

    let mut builder = PluginSchema::builder(name)
        .version(version)
        .category(category)
        .description(description);

    if let Some(obj) = state.as_object() {
        for (key, value) in obj.iter() {
            builder = builder.field(&key.to_string(), field_from_value(value));
        }
    }

    let methods = HashMap::from([
        (
            "GetState".to_string(),
            read_method(
                "GetState",
                "obs.service.factory.get-state@v1",
                empty_args(),
                None,
            ),
        ),
        (
            "SetConfig".to_string(),
            mutation_method(
                "SetConfig",
                "mut.service.factory.set-config@v1",
                serde_json::json!({"type":"object","properties":{}}),
                None,
                false,
            ),
        ),
    ]);
    let signals = vec![signal_decl(
        "ConfigChanged",
        "evt.service.factory.config-changed@v1",
        state_changed_payload(),
    )];
    let guarantees = PluginCapabilities {
        supports_rollback: true,
        supports_checkpoints: true,
        supports_verification: true,
        atomic_operations: false,
    };
    with_caps(
        builder.example(state.clone()).build(),
        methods,
        signals,
        guarantees,
    )
}

/// Infer a `FieldSchema` (type + example) from a live state value.
fn field_from_value(value: &Value) -> FieldSchema {
    FieldSchema {
        field_type: infer_field_type(value),
        required: false,
        description: String::new(),
        default: None,
        example: Some(value.clone()),
        constraints: Vec::new(),
        read_only: false,
        read_only_when: None,
    }
}

/// Infer a `FieldType` from a live state value, recursing into arrays/objects.
fn infer_field_type(value: &Value) -> FieldType {
    use simd_json::prelude::*;

    if value.is_null() {
        FieldType::Any
    } else if value.as_bool().is_some() {
        FieldType::Boolean
    } else if value.as_i64().is_some() || value.as_u64().is_some() {
        FieldType::Integer
    } else if value.as_f64().is_some() {
        FieldType::Float
    } else if value.as_str().is_some() {
        FieldType::String
    } else if let Some(arr) = value.as_array() {
        let inner = arr.first().map(infer_field_type).unwrap_or(FieldType::Any);
        FieldType::Array(Box::new(inner))
    } else if let Some(obj) = value.as_object() {
        let fields = obj
            .iter()
            .map(|(k, v)| (k.to_string(), field_from_value(v)))
            .collect();
        FieldType::Object(fields)
    } else {
        FieldType::Any
    }
}

fn any_field(required: bool, description: &str, default: Option<Value>) -> FieldSchema {
    FieldSchema {
        field_type: FieldType::Any,
        required,
        description: description.to_string(),
        default,
        example: None,
        constraints: Vec::new(),
        read_only: false,
        read_only_when: None,
    }
}

fn simple_schema(
    name: &str,
    description: &str,
    dependencies: &[&str],
    fields: Vec<(&str, FieldSchema)>,
) -> PluginSchema {
    let mut builder = PluginSchema::builder(name)
        .version("1.0.0")
        .description(description);
    for dep in dependencies {
        builder = builder.dependency(dep);
    }
    for (field_name, schema) in fields {
        builder = builder.field(field_name, schema);
    }
    builder.build()
}

