// Extract a `MethodDecl` from the JSON schema object. Returns `None` if the schema does not
    // contain the required top-level fields that indicate a method declaration.
    fn extract_method_decl(schema: &JsonValue) -> Option<MethodDecl> {
        match (
            schema.get("name").and_then(|n| n.as_str()),
            schema.get("args").cloned(),
            schema.get("returns"),
            schema.get("side_effect").and_then(|s| match s.as_str() {
                Some("read") => Some(SideEffect::Read),
                Some("mutation") => Some(SideEffect::Mutation),
                _ => None,
            }),
            schema.get("idempotent").and_then(|i| i.as_bool()),
            schema.get("required_capability").and_then(|c| c.as_str()),
            schema.get("subid").and_then(|s| s.as_str()),
        ) {
            (
                Some(name),
                Some(args),
                returns,
                Some(side_effect),
                idempotent,
                required_capability,
                Some(subid),
            ) => Some(MethodDecl {
                name: name.to_string(),
                args,
                returns: returns.cloned(),
                side_effect,
                idempotent: idempotent.unwrap_or(false),
                required_capability: required_capability.map(str::to_string),
                subid: subid.to_string(),
            }),
            _ => None,
        }
    }

    /// Return the plugin schema for an identifier if present in the combined catalog.
    ///
    /// The combined catalog (`/dev/shm/live-schema.json`) may only cover a subset of plugins.
    /// If a plugin is missing from the combined catalog, its schema can be found in its
    /// own per-plugin schema file (`/dev/shm/opdbus/schemas/<plugin_id>.json`) at the same
    /// path level.
    fn get_schema_for_plugin(&self, plugin_id: &str) -> Option<&JsonValue> {
        if let Some(monolith) = &self.monolith_root { if let Some(plugin_schema) = monolith.get(plugin_id) {
            return Some(plugin_schema);
        } }
        // Per-plugin schema files: `<schema_dir>/<plugin_id>.json`
        let plugin_schema_path = self.schema_dir.join(format!("{}.json", plugin_id));
        if !plugin_schema_path.exists() { return None; }
        match serde_json::from_str::<JsonValue>(&std::fs::read_to_string(plugin_schema_path).ok()?)
        {
            Ok(schema) => Some(schema),
            Err(_) => None,
        }
    }

